#!/usr/bin/env node
/**
 * Generate `packages/minima-rpc/src/commands.generated.ts` from the node command
 * reference emitted by the capability manifest.
 *
 * Usage:
 *   node scripts/generate-minima-rpc-commands.mjs <COMMAND_REFERENCE.md>
 *
 * The reference is generated by hawk-node:
 *   build-kat/gen_command_reference COMMAND_REFERENCE.md
 *
 * Parameter syntax:
 *   [name:value]  required
 *   (name:value)  optional
 *   value:true|false       boolean enum
 *   value:one|two          string enum
 *   value:{}               object
 *   value:[]               array
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = join(ROOT, 'packages', 'minima-rpc', 'src', 'commands.generated.ts');
const referencePath = process.argv[2] ?? process.env.MINIMA_COMMAND_REFERENCE;

if (!referencePath) {
  console.error(
    'usage: node scripts/generate-minima-rpc-commands.mjs <COMMAND_REFERENCE.md>',
  );
  process.exit(1);
}

const text = readFileSync(referencePath, 'utf8');
const rows = [];

for (const line of text.split(/\r?\n/)) {
  const match = /^\| `([^`]+)` \|[^|]*\|[^|]*\| (.*) \|$/.exec(line);
  if (!match) continue;
  rows.push({ name: match[1], summary: match[2].replace(/\\\|/g, '|') });
}

if (rows.length === 0) {
  console.error(`no command rows found in ${referencePath}`);
  process.exit(1);
}

function paramSection(summary) {
  const value = summary.trim();
  if (value.startsWith('- ')) return '';
  let depth = 0;
  for (let i = 0; i < value.length; i += 1) {
    const ch = value[i];
    if (ch === '[' || ch === '(') depth += 1;
    else if (ch === ']' || ch === ')') depth -= 1;
    if (depth !== 0) continue;
    if (value.slice(i, i + 3) === ' - ') return value.slice(0, i);
    if (ch === '-' && value[i + 1] === ' ' && (value[i - 1] === ')' || value[i - 1] === ']')) {
      return value.slice(0, i);
    }
  }
  return value;
}

function parseParams(summary) {
  const section = paramSection(summary);
  const params = [];
  let i = 0;
  while (i < section.length) {
    while (i < section.length && /\s/.test(section[i])) i += 1;
    if (i >= section.length) break;
    const open = section[i];
    if (open !== '[' && open !== '(') {
      // Bare `name:value` tokens are required (e.g. `address:0x..` on
      // mashaddressinfo and `id:..` on mashtxnverify).
      let end = i;
      while (end < section.length && !/\s/.test(section[end])) end += 1;
      const token = section.slice(i, end);
      const colon = token.indexOf(':');
      if (colon > 0) {
        const name = token.slice(0, colon).trim();
        const rawValue = token.slice(colon + 1).trim();
        if (name) params.push({ name, required: true, rawValue });
      }
      i = end;
      continue;
    }
    const close = open === '[' ? ']' : ')';
    let depth = 0;
    let j = i;
    for (; j < section.length; j += 1) {
      if (section[j] === open) depth += 1;
      else if (section[j] === close) depth -= 1;
      if (depth === 0) break;
    }
    const body = section.slice(i + 1, j);
    const colon = body.indexOf(':');
    const name = (colon < 0 ? body : body.slice(0, colon)).trim();
    const rawValue = colon < 0 ? '' : body.slice(colon + 1).trim();
    if (name) params.push({ name, required: open === '[', rawValue });
    i = j + 1;
  }
  return params;
}

const NUMBER_PARAMS = new Set([
  'size', 'page', 'pagesize', 'height', 'depth', 'max', 'offset', 'maxcoins',
  'maxsigs', 'maxhistory', 'keyuses', 'uses', 'count', 'index', 'port',
  'timeout', 'unlockdelay',
]);

function inferParam(param) {
  const { name, required, rawValue } = param;
  if (rawValue.includes('|')) {
    const values = rawValue.split('|').map((v) => v.trim()).filter(Boolean);
    if (values.length === 2 && values.every((v) => v === 'true' || v === 'false')) {
      return { name, type: 'boolean', required, enum: values };
    }
    if (values.length > 1) {
      return { name, type: 'string', required, enum: values };
    }
  }
  if (rawValue === '{}' || rawValue.startsWith('{')) {
    return { name, type: 'object', required };
  }
  if (rawValue === '[]' || (rawValue.startsWith('[') && rawValue.endsWith(']'))) {
    return { name, type: 'array', required };
  }
  if (rawValue === 'true' || rawValue === 'false') {
    return { name, type: 'boolean', required };
  }
  if (NUMBER_PARAMS.has(name)) {
    return { name, type: 'number', required };
  }
  return { name, type: 'string', required };
}

const commands = rows.map((row) => ({
  name: row.name,
  params: parseParams(row.summary).map(inferParam),
}));

const lines = [];
lines.push('/**');
lines.push(' * GENERATED — do not edit by hand.');
lines.push(' *');
lines.push(' * Source: hawk-node COMMAND_REFERENCE.md (totem-node 1.0.100.0, 132 commands).');
lines.push(' * Regenerate: node scripts/generate-minima-rpc-commands.mjs <COMMAND_REFERENCE.md>');
lines.push(' *');
lines.push(' * The node accepts named params, but guarding names/order here catches typos,');
lines.push(' * missing required values and enum drift before a request reaches the node.');
lines.push(' */');
lines.push('');
lines.push("export type MinimaCommandParamType = 'string' | 'number' | 'boolean' | 'object' | 'array';");
lines.push('');
lines.push('export interface MinimaCommandParam {');
lines.push('  readonly name: string;');
lines.push('  readonly type: MinimaCommandParamType;');
lines.push('  readonly required: boolean;');
lines.push('  readonly enum?: readonly string[];');
lines.push('}');
lines.push('');
lines.push('export const MINIMA_COMMAND_PARAMS = {');
for (const command of commands) {
  if (command.params.length === 0) {
    lines.push(`  ${JSON.stringify(command.name)}: [],`);
    continue;
  }
  lines.push(`  ${JSON.stringify(command.name)}: [`);
  for (const param of command.params) {
    const parts = [
      `name: ${JSON.stringify(param.name)}`,
      `type: '${param.type}'`,
      `required: ${param.required}`,
    ];
    if (param.enum) parts.push(`enum: [${param.enum.map((v) => JSON.stringify(v)).join(', ')}]`);
    lines.push(`    { ${parts.join(', ')} },`);
  }
  lines.push('  ],');
}
lines.push('} as const satisfies Record<string, readonly MinimaCommandParam[]>;');
lines.push('');
lines.push('export const MINIMA_COMMAND_NAMES: readonly string[] = Object.freeze(');
lines.push('  Object.keys(MINIMA_COMMAND_PARAMS),');
lines.push(');');
lines.push('');

writeFileSync(OUT, lines.join('\n'));
console.log(`wrote ${OUT} (${commands.length} commands)`);
